import { createReadStream } from 'node:fs'
import { mkdir, rm, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { BadRequestError, NotFoundError } from '../errors/app-error.js'
import type { FileStorage } from './storage.js'

// Keys are UUIDs generated by the API. Anything else (like "../.env") is rejected,
// so a key can never point outside the storage folder.
const KEY_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/

const isNodeError = (error: unknown): error is NodeJS.ErrnoException =>
  error instanceof Error && 'code' in error

export const createLocalStorage = (rootDir: string): FileStorage => {
  const pathFor = (key: string) => {
    if (!KEY_PATTERN.test(key)) throw new BadRequestError('Invalid storage key')
    // Two-level folders (e.g. "01/9a/<key>") keep any single folder from growing too large
    return path.join(rootDir, key.slice(0, 2), key.slice(2, 4), key)
  }

  return {
    async save(key, data) {
      const filePath = pathFor(key)
      await mkdir(path.dirname(filePath), { recursive: true })
      // "wx": create the file and fail if it already exists
      await writeFile(filePath, data, { flag: 'wx' })
    },

    async read(key) {
      const filePath = pathFor(key)
      try {
        await stat(filePath)
      } catch (error) {
        if (isNodeError(error) && error.code === 'ENOENT') {
          throw new NotFoundError('File not found in storage')
        }
        throw error
      }
      return createReadStream(filePath)
    },

    async remove(key) {
      await rm(pathFor(key), { force: true })
    },
  }
}
